mapper.sql:
p.use_yn = 'Y'
AND p.board_type IN ('GENERAL', 'NOTICE', 'QNA') AND p.board_type = #{boardType}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content_text LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT FROM board_calendar_dates c JOIN board_posts p ON p.post_id = c.post_id JOIN members m ON m.member_id = p.author_id LEFT JOIN board_popup_settings s ON s.post_id = p.post_id WHERE p.use_yn = 'Y' AND p.board_type = 'CALENDAR' AND c.event_date < #{endDate} AND COALESCE(c.event_end_date, c.event_date) >= #{startDate}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content_text LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.event_date, p.post_id LIMIT #{limit}

SELECT a.answer_id, a.post_id, a.author_id, m.member_name AS author_name,
    a.content_json, a.content_html, a.content_text, a.created_at
FROM board_answers a JOIN members m ON m.member_id = a.author_id WHERE a.post_id = #{postId}
